"""Compact status output for source targets versus the destination."""
import os
import stat

import dump_command


def run(source, destination, args=None):
    args = list(args or [])
    wanted = []
    i = 0
    while i < len(args):
        a = args[i]
        if a in ('-h', '--help'):
            return '', '', 0
        if a in ('-i', '--include', '-x', '--exclude'):
            i += 1
        elif not a.startswith('-'):
            wanted.append(a)
        i += 1
    dst = os.path.abspath(os.path.expanduser(destination))
    entries = dump_command.load_targets(source)
    if wanted:
        selected = {}
        for rel, entry in entries.items():
            for target in wanted:
                target = os.path.expanduser(target)
                if os.path.isabs(target):
                    try:
                        target = os.path.relpath(target, dst)
                    except ValueError:
                        continue
                if os.path.normpath(target).replace(os.sep, '/') == rel:
                    selected[rel] = entry
        entries = selected
    lines = []
    for rel, entry in sorted(entries.items()):
        path = os.path.join(dst, *rel.split('/'))
        mark = None
        try:
            if entry['type'] == 'symlink':
                if not os.path.islink(path):
                    mark = 'A' if not os.path.lexists(path) else 'M'
                elif os.readlink(path) != entry['linkname']:
                    mark = 'M'
            else:
                if not os.path.exists(path):
                    mark = 'A'
                else:
                    with open(path, 'rb') as f:
                        contents = f.read()
                    if contents != entry['contents'].encode('utf-8') or stat.S_IMODE(os.stat(path).st_mode) != entry['perm']:
                        mark = 'M'
        except OSError:
            mark = 'M'
        if mark:
            lines.append(f' {mark} {rel}\n')
    return ''.join(lines), '', 0

