"""Compact status output for source targets versus the destination."""
import os
import stat

import dump_command
import path_commands


def run(source, destination, args=None, source_path=False):
    args = list(args or [])
    wanted = []
    path_style = "relative"
    include = None
    exclude = set()
    i = 0
    while i < len(args):
        a = args[i]
        if a in ('-h', '--help'):
            return '', '', 0
        if a in ('-p', '--path-style'):
            if i + 1 < len(args):
                path_style = args[i + 1]
                i += 1
        elif a.startswith('--path-style='):
            path_style = a.split('=', 1)[1]
        if a in ('-i', '--include', '-x', '--exclude') and i + 1 < len(args):
            i += 1
            values = set(args[i].split(','))
            if a in ('-i', '--include'):
                include = values
            else:
                exclude |= values
        elif a.startswith('--include='):
            include = set(a.split('=', 1)[1].split(','))
        elif a.startswith('--exclude='):
            exclude |= set(a.split('=', 1)[1].split(','))
        elif not a.startswith('-') and a != 'absolute' and a != 'relative':
            wanted.append(a)
        i += 1
    if path_style not in ('absolute', 'relative'):
        return '', f'chezmoi: invalid argument "{path_style}" for "-p, --path-style" flag: invalid value\n', 1
    valid_types = {'all', 'files', 'scripts', 'symlinks', 'dirs', 'encrypted', 'externals'}
    for kind in (include or set()) | exclude:
        if kind not in valid_types:
            flag = '-i, --include' if include and kind in include else '-x, --exclude'
            return '', f'chezmoi: invalid argument "{kind}" for "{flag}" flag: {kind}: unknown entry type\n', 1
    dst = os.path.abspath(os.path.expanduser(destination))
    entries = dump_command.load_targets(source)
    allowed = include or {'files', 'symlinks', 'scripts', 'dirs', 'encrypted', 'externals'}
    if 'all' in allowed:
        allowed = valid_types - {'all'}
    allowed -= exclude
    entries = {k: v for k, v in entries.items()
               if ('symlinks' if v.get('type') == 'symlink' else 'files') in allowed}
    if wanted:
        targets = []
        for target in wanted:
            if source_path:
                source_abs = os.path.abspath(os.path.expanduser(source))
                source_input = os.path.abspath(os.path.expanduser(target))
                try:
                    if os.path.commonpath((source_input, source_abs)) != source_abs:
                        return '', f'chezmoi: {source_input}: not in {source_abs}\n', 1
                except ValueError:
                    return '', f'chezmoi: {source_input}: not in {source_abs}\n', 1
                if not os.path.lexists(source_input):
                    return '', f'chezmoi: {target}: not in source state\n', 1
                try:
                    target_path = path_commands.source_to_target(target, source, destination)
                except ValueError as e:
                    return '', f'chezmoi: {e}\n', 1
                absolute = os.path.abspath(target_path)
            else:
                absolute = os.path.abspath(os.path.expanduser(target))
            try:
                inside = os.path.commonpath((absolute, dst)) == dst
            except ValueError:
                inside = False
            if not inside:
                return '', f'chezmoi: {absolute}: not in destination directory ({destination})\n', 1
            rel = os.path.relpath(absolute, dst).replace(os.sep, '/')
            if rel not in entries and not any(k.startswith(rel.rstrip('/') + '/') for k in entries):
                return '', f'chezmoi: {absolute}: not managed\n', 1
            targets.append(rel)
        selected = {rel: entry for rel, entry in entries.items()
                    if any(rel == target or rel.startswith(target.rstrip('/') + '/') for target in targets)}
        entries = selected
    lines = []
    for rel, entry in sorted(entries.items()):
        path = os.path.join(dst, *rel.split('/'))
        mark = None
        try:
            if entry['type'] == 'symlink':
                if not os.path.islink(path):
                    mark = 'A' if not os.path.lexists(path) else 'M'
                elif os.readlink(path) != entry['linkname']:
                    mark = 'M'
            else:
                if not os.path.exists(path):
                    mark = 'A'

