def _render(text, data):
    # Cover the common Go-template constructs used for dotfile templates.
    def lookup(expr):
        expr = expr.strip()
        if expr.startswith("."):
            value = data
            for key in expr[1:].split("."):
                if not key:
                    continue
                if isinstance(value, dict) and key in value:
                    value = value[key]
                else:
                    return None, False
            return value, True
        if expr in ("true", "false"):
            return expr == "true", True
        if expr in ("nil", "null"):
            return None, True
        if re.fullmatch(r"-?\d+", expr):
            return int(expr), True
        if re.fullmatch(r"-?\d+\.\d+", expr):
            return float(expr), True
        if len(expr) >= 2 and expr[0] == expr[-1] and expr[0] in ('"', "'"):
            return expr[1:-1], True
        try:
            words = shlex.split(expr)
        except ValueError:
            words = []
        if words:
            if words[0] == "list":
                return words[1:], True
            if words[0] == "dict" and len(words) % 2 == 1:
                return dict(zip(words[1::2], words[2::2])), True
            if words[0] == "not" and len(words) == 2:
                value, found = lookup(words[1])
                return (not value, found)
            if words[0] == "len" and len(words) == 2:
                value, found = lookup(words[1])
                try:
                    return len(value), found
                except TypeError:
                    return None, False
        return expr, True

    # Simple conditionals, including an optional else branch.
    block = re.compile(r"{{\s*if\s+([^{}]+?)\s*}}(.*?){{\s*end\s*}}", re.S)
    while True:
        match = block.search(text)
        if not match:
            break
        condition, body = match.group(1), match.group(2)
        value, found = lookup(condition)
        yes, no = body, ""
        split = re.search(r"{{\s*else\s*}}", body)
        if split:
            yes, no = body[:split.start()], body[split.end():]
        truth = found and value not in (None, False, "", 0, [], {})
        text = text[:match.start()] + _render(yes if truth else no, data) + text[match.end():]

    def stringify(value):
        if isinstance(value, bool):
            return str(value).lower()
        if value is None:
            return "<no value>"
        return str(value)

    def sub(match):
        action = match.group(1).strip()
        bits = [part.strip() for part in action.split("|")]
        expr = bits[0]
        # Go's printf takes the format before the value.
        printf = re.fullmatch(r'printf\s+"((?:[^"\\]|\\.)*)"\s+(.+)', expr)
        if printf:
            value, found = lookup(printf.group(2))
            if not found:
                return match.group(0)
            fmt = printf.group(1)
            try:
                result = fmt.replace("%s", stringify(value)).replace("%v", stringify(value))
            except Exception:
                result = stringify(value)
        else:
            value, found = lookup(expr)
            if not found:
                return match.group(0)
            result = value
        for fn in bits[1:]:
            call = re.fullmatch(r"([A-Za-z][A-Za-z0-9_]*)\s+(.+)", fn)
            if call:
                name, arg_expr = call.groups()
                try:
                    arg_exprs = shlex.split(arg_expr)
                except ValueError:
                    return match.group(0)
                args = [lookup(x) for x in arg_exprs]
                if not args or any(not found for _, found in args):
                    return match.group(0)
                values = [value for value, _ in args]
                arg = values[0]
                try:
                    if name in ("add", "add1"):
                        result = result + (1 if name == "add1" else arg)
                    elif name in ("sub", "subtract"):
                        result = result - arg
                    elif name in ("mul", "multiply"):
                        result = result * arg
                    elif name in ("div", "divide"):
                        result = result / arg
                    elif name == "mod":
                        result = result % arg
                    elif name in ("max", "min"):
                        result = max(result, arg) if name == "max" else min(result, arg)
                    elif name == "trimPrefix":
                        result = stringify(result).removeprefix(stringify(arg))
                    elif name == "trimSuffix":
                        result = stringify(result).removesuffix(stringify(arg))
                    elif name == "splitList":
                        result = stringify(result).split(stringify(arg))
                    elif name == "join":
                        result = stringify(arg).join(stringify(x) for x in result)
                    elif name == "hasPrefix":
                        result = stringify(result).startswith(stringify(arg))
                    elif name == "hasSuffix":
                        result = stringify(result).endswith(stringify(arg))
                    elif name == "contains":
                        result = stringify(arg) in stringify(result)
                    elif name == "replace" and len(values) >= 2:
                        result = stringify(result).replace(stringify(values[0]), stringify(values[1]))
                    elif name == "default":
                        if result in (None, False, "", 0, [], {}): result = arg
                    elif name == "quote":
                        result = json.dumps(stringify(result), ensure_ascii=False)
                    elif name == "toString":
                        result = stringify(result)
                    else:
                        return match.group(0)
                except (TypeError, ValueError, ZeroDivisionError):
                    return match.group(0)
                continue
            if fn == "upper":
                result = stringify(result).upper()
            elif fn == "lower":
                result = stringify(result).lower()
            elif fn == "title":
                result = stringify(result).title()
            elif fn in ("trim", "trimSpace"):
                result = stringify(result).strip()
            elif fn in ("toJson", "json"):
                result = json.dumps(result, ensure_ascii=False, separators=(",", ":"))
            elif fn == "quote":
                result = json.dumps(stringify(result), ensure_ascii=False)
            elif fn == "squote":
                result = "'" + stringify(result).replace("'", "\\'") + "'"
            else:
                return match.group(0)
        return stringify(result)
    return re.sub(r"{{\s*([^{}]+?)\s*}}", sub, text)


