"""Source-state metadata commands (chattr and forget)."""
import os


def _target_rel(path, dest):
    p = os.path.abspath(os.path.expanduser(path))
    d = os.path.abspath(os.path.expanduser(dest))
    try:
        return os.path.relpath(p, d)
    except ValueError:
        return path


def _source_entry(source, target):
    """Find a source entry for a destination-relative target."""
    target = target.replace('\\', '/')
    if os.path.isdir(source):
        for root, dirs, files in os.walk(source):
            for name in files + dirs:
                p = os.path.join(root, name)
                rel = os.path.relpath(p, source)
                decoded = []
                for part in rel.split(os.sep):
                    if part.endswith('.tmpl'):
                        part = part[:-5]
                    prefixes = ('run_onchange_', 'run_once_', 'private_', 'executable_', 'readonly_',
                                'encrypted_', 'empty_', 'create_', 'modify_', 'symlink_', 'exact_',
                                'remove_', 'before_', 'after_', 'once_', 'run_')
                    while True:
                        prefix = next((prefix for prefix in prefixes if part.startswith(prefix)), None)
                        if prefix is None:
                            break
                        part = part[len(prefix):]
                    if part.startswith('dot_'):
                        part = '.' + part[4:]
                    decoded.append(part)
                if '/'.join(decoded) == target:
                    return p
    return None


def _encode_attribute(name, attribute, enabled):
    prefixes = {'private': 'private_', 'executable': 'executable_', 'readonly': 'readonly_',
                'empty': 'empty_', 'create': 'create_', 'modify': 'modify_', 'exact': 'exact_',
                'remove': 'remove_', 'before': 'before_', 'after': 'after_', 'encrypted': 'encrypted_',
                'script': 'run_', 'once': 'run_once_', 'onchange': 'run_onchange_', 'symlink': 'symlink_'}
    template = name.endswith('.tmpl')
    if template:
        name = name[:-5]
    active = set()
    ordered = sorted(prefixes.items(), key=lambda item: len(item[1]), reverse=True)
    while True:
        found = next(((attr, prefix) for attr, prefix in ordered if name.startswith(prefix)), None)
        if found is None:
            break
        active.add(found[0])
        name = name[len(found[1]):]
    if attribute in prefixes:
        if enabled:
            active.add(attribute)
        else:
            active.discard(attribute)
    if attribute == 'template':
        template = enabled
    for attr in ('remove', 'private', 'executable', 'readonly', 'encrypted', 'create', 'modify',
                 'empty', 'exact', 'symlink', 'before', 'after', 'onchange', 'once', 'script'):
        if attr in active:
            name = prefixes[attr] + name
    if template:
        name += '.tmpl'
    return name


_ATTRS = {'after', 'before', 'empty', 'encrypted', 'exact', 'executable',
          'external', 'once', 'onchange', 'private', 'readonly', 'remove',
          'template', 'create', 'modify', 'script', 'symlink'}


def chattr(source, destination, args, dry_run=False):
    clean = []
    recursive = False
    for arg in args:
        if arg in ('-r', '--recursive'):
            recursive = True
        elif arg != '--':
            clean.append(arg)
    if len(clean) < 2:
        return '', f'chezmoi: requires at least 2 arg(s), only received {len(clean)}\n', 1
    modifiers = clean[0].split(',')
    rc, out, err = 0, [], []
    for mod in modifiers:
        attr = mod[2:] if mod.startswith('no') else mod[1:] if mod.startswith(('-', '+')) else mod
        attr = {'x': 'executable', 'p': 'private', 'r': 'readonly', 't': 'template', 'o': 'once', 'e': 'empty', 'a': 'after', 'b': 'before'}.get(attr, attr)
        if attr not in _ATTRS:
            return '', f'chezmoi: {attr}: unknown attribute\n', 1
    for arg in clean[1:]:
        target = _target_rel(arg, destination)
        entry = _source_entry(source, target)
        if not entry:
            rc = 1
            err.append(f'chezmoi: {os.path.abspath(os.path.expanduser(arg))}: not managed\n')
            continue
        entries = [entry]
        if recursive and os.path.isdir(entry) and not os.path.islink(entry):
            for root, dirs, files in os.walk(entry):
                entries.extend(os.path.join(root, name) for name in dirs + files)
            entries.sort(key=lambda p: (p.count(os.sep), p), reverse=True)
        for item in entries:
            newname = os.path.basename(item)
            for mod in modifiers:
                enabled = not (mod.startswith('no') or mod.startswith('-'))
                attr = mod[2:] if mod.startswith('no') else mod[1:] if mod.startswith(('-', '+')) else mod
                attr = {'x': 'executable', 'p': 'private', 'r': 'readonly', 't': 'template', 'o': 'once', 'e': 'empty', 'a': 'after', 'b': 'before'}.get(attr, attr)
                newname = _encode_attribute(newname, attr, enabled)
            dest = os.path.join(os.path.dirname(item), newname)
            if dest != item and not dry_run:
                try:
                    if os.path.lexists(dest):
                        raise FileExistsError(dest)
                    os.rename(item, dest)
                except OSError as e:
                    rc = 1
                    err.append(f'chezmoi: {e}\n')
    return ''.join(out), ''.join(err), rc


def forget(source, destination, args, force=False, dry_run=False):
    if not args:
        return '', 'chezmoi: requires at least 1 arg(s), only received 0\n', 1
    rc, out, err = 0, [], []
    for arg in args:
        entry = _source_entry(source, _target_rel(arg, destination))
        if not entry:
            rc = 1
            err.append(f'chezmoi: {os.path.abspath(os.path.expanduser(arg))}: not managed\n')
            continue
        if not force:
            out.append(f'Remove {entry}?\n')
            err.append('chezmoi: could not open a new TTY: open /dev/tty: no such device or address\n')
            rc = 1
            continue
        if not dry_run:
            try:
                if os.path.isdir(entry) and not os.path.islink(entry):
                    os.rmdir(entry)
                else:
                    os.unlink(entry)
            except OSError as e:
                rc = 1
                err.append(f'chezmoi: {e}\n')
    return ''.join(out), ''.join(err), rc
